    ay_fin_devuelto_cuando: "Al cuadrar la caja del mes: sobra efectivo que el sistema sigue contando como dinero afuera.",
    ay_fin_descuento_para: "Ver lo que alguien gastó de más y no se devolvió en efectivo.",
    ay_fin_descuento_cuando: "Cuando alguien se pasa la semana esperando en caja un dinero que nunca va a llegar ahí: este se descuenta en nómina.",
    ay_srv_viaticos_para: "Ver el dinero de este servicio: qué se le asignó a cada quien, si ya salió y si ya se comprobó.",
