    ay_srv_viaticos_numero: "El monto lo propone el tabulador del acuerdo por los días de esa persona; el consultor lo autoriza y finanzas lo deposita.",
    ay_srv_cambios_para: "Ver quién entró por quién y qué unidad relevó a cuál, con la hora en que pasó.",
    ay_srv_cambios_cuando: "El día de pago, cuando el que se presentó esa mañana y se fue a media jornada llama a preguntar por qué no le pagaron su día.",
