    srv_cierre_en: "El cierre está en {e}.",
    ay_srv_visto_bueno_para: "Revisar que el servicio quedó bien y mandarlo a facturar, dentro de las 24 horas que corren desde que terminó.",
    ay_srv_visto_bueno_cuando: "Al día siguiente, cuando el plazo ya pasó: el servicio se factura tarde y la comisión de ese servicio se pierde.",
    ay_srv_revision_para: "Comparar cómo estaba la unidad al recibirla y cómo volvió, lado a lado y con la misma foto desde el mismo ángulo.",
    ay_srv_revision_cuando: "Tres semanas después, cuando aparece un golpe y hay que decidir quién lo paga sin nada con qué comparar. Lo termina pagando el último que la trajo.",
    ay_srv_revision_numero: "Los kilómetros recorridos salen de restar los dos tableros. La foto del odómetro es la que los hace comprobables.",
    ay_pan_paises_para: "Ver de un golpe qué hay en la calle ahora mismo en cada país, con su hora local.",
    ay_pan_paises_cuando: "Nunca, y ese es el problema: un país sin renglones se lee como un día tranquilo, y puede ser un día que nadie reportó.",
    ay_pan_paises_numero: "Son los servicios con un equipo en curso en ese momento, contados con el reloj de ese país y no con el del servidor.",
    ay_pan_hoy_para: "Seguir el día de ese país hora por hora: quién ya arrancó, quién va en camino y quién todavía no marca.",
    ay_pan_hoy_cuando: "Cuando el cliente llama a preguntar dónde está su equipo. Para entonces llevan media hora esperando.",
    ay_pan_dinero_para: "Ver dónde está el dinero de los viáticos: lo que se pidió y no ha salido, y lo que salió y no se ha comprobado.",
    ay_pan_dinero_cuando: "Al cerrar el mes, cuando la caja no cuadra y ya nadie se acuerda de qué depósito era cuál.",
    ay_pan_dinero_numero: "Comprometido es lo que el consultor ya autorizó y finanzas no ha depositado. Afuera es lo depositado que todavía nadie comprobó.",
    ay_pan_regresados_para: "Ver el efectivo que la gente devolvió de lo que no gastó.",
    ay_pan_regresados_cuando: "Al cuadrar la caja: el sistema dice que hay dinero afuera y está en el cajón desde el martes.",
    ay_pan_calidad_para: "Saber si lo que nos reportan es cierto, no si la operación va bien. Son dos preguntas distintas.",
    ay_pan_calidad_cuando: "Nunca de golpe: estas cifras solo se ven al cerrar cada servicio, una por una. Un patrón —alguien que siempre marca desde lejos— no se ve así.",
    ay_pan_calidad_numero: "Los intentos fuera de geocerca son marcas rechazadas: alguien quiso reportar que ya llegó desde lejos. Las marcas por validar las tiene que revisar la central.",
    ay_cen_pulso_para: "Ver los servicios que están corriendo ahora y, sobre todo, cuánto lleva callado cada uno.",
    ay_cen_camino_para: "Saber si va a haber alguien en el punto. No mide "
      + "puntualidad: mide si la persona se está moviendo hacia allá.",
    ay_cen_camino_cuando: "Cuando alguien aparece aquí como \"Sin "
      + "respuesta\" o \"No llega\". A esa hora todavía se puede mandar a "
      + "otra persona; una hora después, ya no.",
    ay_cen_pulso_cuando: "Cuando el equipo vuelve a reportar y todo estaba bien. O cuando no vuelve, y entonces ya pasó algo.",
    ay_cen_pulso_numero: "El silencio se cuenta desde la última marca o reporte de ese equipo, con la hora de su país.",
    ay_cen_semana_para: "Ver lo que viene, para llegar antes: confirmaciones que faltan, gente sin asignar, viáticos sin depositar.",
    ay_cen_semana_cuando: "A las seis de la mañana del día del servicio, que es cuando lo que se resolvía con una llamada la víspera ya cuesta un servicio.",
    ay_cen_sin_cerrar_para: "La lista de trabajo de la central: días que ya pasaron y siguen abiertos.",
    ay_cen_sin_cerrar_cuando: "El día de pago, cuando esa gente no aparece en el corte y llama a preguntar. Nadie reclama antes.",
    ay_alta_inicio_para: "Fijar dónde y a qué hora se presenta el equipo el primer día. De ahí cuelga todo lo demás.",
    ay_alta_inicio_cuando: "La mañana del servicio: el equipo no puede marcar su llegada, el día no arranca y la central no sabe si llegaron.",
    ay_alta_dias_para: "Armar los días del servicio: cuántos son, a qué hora empieza cada uno y con qué modalidad.",
    ay_alta_dias_cuando: "El día que falta: nadie se presenta porque para el sistema ese día no existe. Y no se cobra.",
    ay_alta_equipos_para: "Partir el servicio cuando hay más de un ejecutivo o más de un punto de salida. Cada equipo lleva su gente, su unidad y su hoja.",
    ay_alta_equipos_cuando: "Cuando el cliente abre su hoja y lee nombres de gente que no va con él, y llama a preguntar quiénes son.",
    ay_alta_minimo_para: "Ver en todo momento qué falta para que el servicio quede programado.",
    ay_alta_minimo_cuando: "La mañana del servicio, con lo que falta puesto enfrente y sin tiempo para resolverlo.",
    ay_acc_historial_para: "Ver qué se le ha hecho a este acceso y quién lo hizo, con el motivo que se escribió.",
    ay_acc_historial_cuando: "Un año después, cuando alguien pregunta por qué se cerró esa cuenta y nadie se acuerda.",
    ay_cat_puesto_para: "Poner o quitar el puesto de esta persona. El puesto manda sobre su rol.",
    ay_cat_puesto_cuando: "Cuando esa persona entra y puede tocar lo mismo que todos los de su rol, que es justo lo que se quería evitar.",
    ay_cat_permisos_para: "Ver todo lo que esta persona puede y de dónde le viene cada cosa: su puesto, su rol o un permiso suelto.",
    ay_cat_permisos_cuando: "Cuando alguien llama diciendo que no puede hacer algo y hay que abrir el código para saber por qué.",
    ay_imp_trato_para: "Guardar lo que no cambia de mes a mes: qué cubre el servicio, hasta dónde llega y dónde se presenta el equipo todos los días.",
    ay_imp_trato_cuando: "Al segundo mes, cuando hay que volver a capturarlo. Y al sexto, cuando cambia algo y hay seis copias que corregir.",
    ay_imp_hoja_para: "La hoja que ve el cliente y que lleva quien llega a cubrir un día.",
    ay_imp_hoja_cuando: "Cuando llega alguien a cubrir un día y pregunta por radio dónde se presenta, porque lo de siempre no le dice nada a quien no estuvo.",
    ay_imp_plantilla_para: "Decir quién va todos los días del mes, con qué rol y en qué unidad. El día lo hereda al generarse.",
    ay_imp_plantilla_cuando: "Cada mañana del mes, armando el equipo a mano. Y el día que se olvide un conductor, cuando la unidad se queda estacionada.",
    ay_imp_calendario_para: "Abrir los días del mes según lo contratado, y ver cuáles están cubiertos y cuáles no.",
    ay_imp_calendario_cuando: "El sábado a las siete, cuando el fin de semana contratado abrió vacío y no hay quien lo cubra. Se abre así a propósito: quien trabajó de lunes a viernes descansa.",
    ay_imp_calendario_numero: "Los días base son los que marca el calendario del mes, no un número fijo. Los fines de semana se cobran aparte como días adicionales.",
    ay_imp_taller_para: "Sacar una unidad de circulación y poner otra en su lugar, en un solo paso.",
    ay_imp_taller_cuando: "Cuando se le promete al cliente un vehículo que está desarmado en el taller, porque seguía apareciendo libre.",
    ay_imp_tabulador_para: "Lo que se acordó con este cliente por día y por persona: comida, traslado, gasolina.",
