    ay_mg_mano_cuando: "Cuando el cliente ya confirmó por teléfono que el equipo está con él y en el sistema no hay marca: se quedaron sin batería, sin señal, o simplemente se les pasó. No es lo mismo que ajustar un hito, que corrige la hora de una marca que sí existe. Esta crea una que nunca se hizo, no lleva ubicación, y queda firmada con su nombre para siempre: de esa hora salen las horas extra que se le facturan al cliente.",
