    bit_corregir_faltan: "Missing data: the time and the reason are required. The reason takes at least five characters.",
    bit_reabrir_titulo: "Reopen the day",
    bit_reabrir_pie: "Undoes the closing so the day can be worked or closed again. If the team closed it from the street, their end mark is voided: it is not deleted, it keeps your name and the reason.",
    bit_reabrir_ph: "Why it is reopened",
    bit_reabrir_falta: "Write why it is reopened.",
    bit_reabrir_seguro: "Reopen this day? If the team closed it, their end mark is voided.",
    bit_reabrir_boton: "Reopen the day",
    ay_bit_reabrir_para: "Undo the closing of a day closed by mistake, or closed too early because the team kept working.",
    ay_bit_reabrir_cuando: "When a day stays wrongly closed: it enters payroll with the wrong hours, or the team cannot mark its end again.",
    bit_manana_titulo: "Tomorrow we start at…",
    bit_manana_pie: "Changes the start time of this team's next day ({fecha}) and notifies anyone who had already confirmed.",
