    bit_manana_guardar: "Set tomorrow's time",
    bit_manana_falta: "The time is missing.",
    ay_bit_manana_para: "Set the time this team's next day starts, at the moment the principal says it.",
    ay_bit_manana_cuando: "At the end of the day, when the executive says what time they meet tomorrow. It moves the start time of THIS team's next day — another team in another city is untouched — and notifies anyone who had already confirmed against the old time: a confirmation made against a time that changed points at something no longer true.",
