    ay_mg_mano_cuando: "Quando o cliente já confirmou por telefone que a equipe está com ele e no sistema não há marca: ficaram sem bateria, sem sinal, ou simplesmente passou. Não é o mesmo que ajustar um marco, que corrige a hora de uma marca que existe. Esta cria uma que nunca foi feita, não leva localização, e fica assinada com o seu nome para sempre: dessa hora saem as horas extras faturadas ao cliente.",
